before:
Complete local C++ example; the app itself does not execute it:
```cpp
#include <chrono>
#include <iostream>
int main() {
    auto elapsed = std::chrono::milliseconds{1750};
    auto wholeSeconds = std::chrono::duration_cast<std::chrono::seconds>(elapsed);
    std::cout << wholeSeconds.count() << "\n";
}
```

